import{_ as a,o as e,c as d,a5 as o}from"./chunks/framework.BEZBAInb.js";const b=JSON.parse('{"title":"演员切换状态","description":"","frontmatter":{"title":"演员切换状态","order":4},"headers":[],"relativePath":"zh/latest/tutorial/script/actor/actor-change-state.md","filePath":"zh/latest/tutorial/script/actor/actor-change-state.md","lastUpdated":1788455378000}'),r={name:"zh/latest/tutorial/script/actor/actor-change-state.md"};function i(s,t,n,c,l,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="演员切换状态" tabindex="-1">演员切换状态 <a class="header-anchor" href="#演员切换状态" aria-label="Permalink to &quot;演员切换状态&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p>切换指定演员的状态。能安全提供状态帧的角色会进行新旧画面交融；其他角色会自动使用淡出、应用状态、淡入的安全转场。转场完成后继续执行剧情。</p><h2 id="语法结构" tabindex="-1">语法结构 <a class="header-anchor" href="#语法结构" aria-label="Permalink to &quot;语法结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change &lt;角色名称&gt; &lt;新状态&gt;</span></span></code></pre></div><h2 id="参数详解" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解" aria-label="Permalink to &quot;参数详解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>角色</td><td>是</td><td>kona</td><td>指定要切换状态的演员名称</td></tr><tr><td>新状态</td><td>是</td><td>happy</td><td>指定要切换到的新状态</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change kona happy</span></span></code></pre></div><h2 id="状态切换转场" tabindex="-1">状态切换转场 <a class="header-anchor" href="#状态切换转场" aria-label="Permalink to &quot;状态切换转场&quot;">​</a></h2><p><code>actor change</code> 会自动选择转场方式：</p><ol><li>角色场景能提供当前与目标状态帧时，使用预乘 Alpha shader 进行像素交融。</li><li>无法安全提供状态帧时，依次淡出当前角色、应用状态并淡入。</li><li>转场结束后，继续执行下一条剧情命令。</li></ol><p>在 <code>KonadoStageController</code> 节点的检查器中可以配置转场：</p><table tabindex="0"><thead><tr><th>属性</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>actor_state_transition_enabled</code></td><td><code>true</code></td><td>是否为演员状态切换启用淡入淡出</td></tr><tr><td><code>actor_state_transition_duration</code></td><td><code>0.3</code></td><td>完整转场的总时长（秒）；安全降级时淡出和淡入各占一半</td></tr></tbody></table><p>关闭 <code>actor_state_transition_enabled</code> 或把 <code>actor_state_transition_duration</code> 设为 <code>0</code> 时，状态会立即切换。</p><p>转场不会复制角色场景。内置 AnimatedSprite2D 示例通过纯纹理状态帧实现真正交融；自定义状态帧必须完整表示角色画面，不能只包含其中一个可见部件。视频、Spine、Live2D 和无法提供完整安全状态帧的自定义角色场景会自动降级，不会重复运行脚本、音频或动态媒体。目标演员不存在或角色场景无法应用该状态时，系统会结束本次命令并继续剧情，不会一直等待。</p>',16)])])}const u=a(r,[["render",i]]);export{b as __pageData,u as default};
